import numpy as np
import torch

# Check if the input is a torch.Tensor or np.ndarray
if isinstance(batch, (torch.Tensor, np.ndarray)):
    # If it's already a tensor or array, just add a new dimension
    return torch.unsqueeze(batch, 0) if isinstance(batch, torch.Tensor) else np.expand_dims(batch, axis=0)

# Check if the input is a tuple or list
elif isinstance(batch, (tuple, list)):
    # Use a list comprehension to recursively add the new dimension to each element
    return torch.stack([add_batch(item) for item in batch]) if isinstance(batch, list) else torch.stack([add_batch(item) for item in batch])

# Check if the input is a dict
elif isinstance(batch, dict):
    # Convert the dictionary to a dotmap for easier access to its values
    batch = DotMap(batch)

    # Create a new dictionary with the same keys and recursively apply add_batch to each value
    new_batch = DotMap()
    for key, value in batch.items():
        new_batch[key] = add_batch(value)

    # Convert the dotmap back to a regular dictionary
    return new_batch.toDict()

# If the input is none of the above, just return it as is
else:
    return batch

